JsonObject LegacySnapshot(World source,string v4File,int version,bool fourMember=false)
{
 var root=JsonNode.Parse(File.ReadAllText(v4File))!.AsObject();root["Version"]=version;if(version<3)root.Remove("PartyOrder");if(version<4){root.Remove("MessageHistory");root.Remove("NextMessageSequence");}
 var actors=root["Actors"]!.AsArray();
 for(int i=actors.Count-1;i>=0;i--)
 {
  var node=actors[i]!.AsObject();string id=node["Id"]!.GetValue<string>();var actor=source.Actors.First(a=>a.Id==id);
  if(fourMember&&!actor.Enemy&&(id is "rogue" or "bard")){actors.RemoveAt(i);continue;}
  string legacyClass=actor.Enemy?actor.CreatureKind:id switch{"knight"=>"Knight","ranger"=>"Ranger","mage"=>"Mage","cleric"=>"Cleric","rogue"=>"Rogue","bard"=>"Bard",_=>actor.Class};
  node["Class"]=legacyClass;node["Hp"]=actor.Hp;node["MaxHp"]=actor.MaxHp;node["BaseAc"]=actor.BaseAc;node["Dex"]=actor.Dex;node["Bonus"]=actor.Bonus;node["Die"]=actor.Die;node["Range"]=actor.Range;node["Mana"]=actor.Mana;node["MaxMana"]=actor.MaxMana;node["Guarding"]=false;node["Weapon"]=actor.Weapon;node["Armor"]=actor.Armor;node["Charm"]=actor.Charm;
  node.Remove("Character");node.Remove("CreatureKind");if(version==1){node.Remove("Position");node.Remove("FacingLeft");}
 }
 if(fourMember&&root["PartyOrder"] is JsonArray order)for(int i=order.Count-1;i>=0;i--)if(order[i]!.GetValue<string>() is ("rogue" or "bard"))order.RemoveAt(i);
 return root;
