var maelinChecks=DialogueCatalog.Get("sister-maelin").Nodes.SelectMany(n=>n.Choices).Where(c=>c.Check!=null).ToArray();
Check(serelChecks.Any(c=>c.Check!.Skill==Skill.Insight)&&serelChecks.Any(c=>c.Check!.Skill==Skill.Persuasion)&&serelChecks.Any(c=>c.Check!.Ability==Ability.Intelligence),"IIP39 authored dialogue demonstrates Insight, Persuasion, and a raw ability check without hard-coding them into the UI");
var socialSkills=maelinChecks.Select(c=>c.Check!.Skill).Where(s=>s.HasValue).Select(s=>s!.Value).ToHashSet();
Check(socialSkills.SetEquals(new[]{Skill.Persuasion,Skill.Deception,Skill.Intimidation}),"IIP39 authored social dialogue demonstrates Persuasion, Deception, and Intimidation through the generic skill-check model");
Check(DialogueCatalog.All.All(d=>d.Nodes.All(n=>n.Choices.All(c=>c.Check==null||((c.Check.SuccessEndsConversation||d.Nodes.Any(x=>x.Id==c.Check.SuccessNodeId))&&(c.Check.FailureEndsConversation||d.Nodes.Any(x=>x.Id==c.Check.FailureNodeId)))))),"IIP39 every checked response has valid authored success and failure destinations");
var persuasionCheck=maelinChecks.First(c=>c.Check!.Skill==Skill.Persuasion).Check!;
Check(DialogueCheckRules.Modifier(checkBard,persuasionCheck)==checkBard.SkillModifier(Skill.Persuasion)&&DialogueCheckRules.Label(persuasionCheck)=="Persuasion","IIP39 dialogue preview derives the visible skill modifier from the captured speaking character's 5e sheet");
var alternateAbility=new DialogueCheckDefinition(10,"success","failure",Skill:Skill.Persuasion,AbilityOverride:Ability.Strength);
Check(DialogueCheckRules.Modifier(checkBard,alternateAbility)==checkBard.AbilityModifier(Ability.Strength)+checkBard.ProficiencyBonus&&DialogueCheckRules.Label(alternateAbility)=="Strength (Persuasion)","IIP39 supports 5e alternate-ability skill checks while preserving the skill proficiency rank");
var rawAbility=new DialogueCheckDefinition(10,"success","failure",Ability:Ability.Wisdom);
Check(DialogueCheckRules.Modifier(checkBard,rawAbility)==checkBard.AbilityModifier(Ability.Wisdom)&&DialogueCheckRules.Label(rawAbility)=="Wisdom","IIP39 supports ability-only dialogue checks in addition to named skills");
int checkSuccessBefore=checkBard.Statistics.SuccessfulSkillChecks,checkFailBefore=checkBard.Statistics.FailedSkillChecks;uint checkSeed=checkWorld.RandomState;
var guaranteedSuccess=checkWorld.ResolveDialogueCheck(checkBard,new DialogueCheckDefinition(1,"success","failure",Skill:Skill.Persuasion));
Check(guaranteedSuccess.Success&&guaranteedSuccess.Total==guaranteedSuccess.ChosenRoll+guaranteedSuccess.Modifier&&checkBard.Statistics.SuccessfulSkillChecks==checkSuccessBefore+1&&checkWorld.RandomState!=checkSeed,"IIP39 Core resolves dialogue checks with the deterministic world d20 authority and records successful ability checks");
var guaranteedFailure=checkWorld.ResolveDialogueCheck(checkBard,new DialogueCheckDefinition(30,"success","failure",Skill:Skill.Persuasion));
Check(!guaranteedFailure.Success&&checkBard.Statistics.FailedSkillChecks==checkFailBefore+1,"IIP39 dialogue check failure uses total-versus-DC semantics rather than automatic natural-1/natural-20 outcomes");
var advantageResult=checkWorld.ResolveDialogueCheck(checkBard,new DialogueCheckDefinition(30,"success","failure",Skill:Skill.Deception,RollMode:DialogueCheckRollMode.Advantage));
Check(advantageResult.SecondRoll>0&&advantageResult.ChosenRoll==Math.Max(advantageResult.FirstRoll,advantageResult.SecondRoll),"IIP39 check metadata can request 5e advantage without putting dice logic in the dialogue renderer");
var disadvantageResult=checkWorld.ResolveDialogueCheck(checkBard,new DialogueCheckDefinition(30,"success","failure",Skill:Skill.Intimidation,RollMode:DialogueCheckRollMode.Disadvantage));
Check(disadvantageResult.SecondRoll>0&&disadvantageResult.ChosenRoll==Math.Min(disadvantageResult.FirstRoll,disadvantageResult.SecondRoll),"IIP39 check metadata can request 5e disadvantage through the same Core authority");
Check(checkWorld.MessageHistory.Any(m=>m.Category==MessageCategory.Roll&&m.Detail.Contains("Persuasion check")&&m.Detail.Contains("vs DC")),"IIP39 dialogue rolls write full modifier arithmetic and success/failure outcomes to the durable Roll log");

