var preferenceBoundaryWorld=Peace();preferenceBoundaryWorld.Difficulty=DifficultyPreset.Ruthless;var preferenceBoundaryFile=Path.Combine(Path.GetTempPath(),"ashen-iip45-preference-boundary-"+Guid.NewGuid()+".json");preferenceBoundaryWorld.Save(preferenceBoundaryFile);var preferenceBoundaryJson=File.ReadAllText(preferenceBoundaryFile);Check(!preferenceBoundaryJson.Contains("\"Difficulty\"",StringComparison.Ordinal),"IIP45 difficulty is a profile preference and does not silently mutate the v14 journey schema");File.Delete(preferenceBoundaryFile);


// IIP47 — Character Creation: a complete player-facing draft validates into the same 5e actor/runtime model used by the campaign.
var creation=CharacterCreationRules.NewDraft();creation.Name="Aren Vale";creation.Pronouns="they/them";creation.VoiceSet="Wry";creation.Portrait=4;creation.SpeciesId="Wood Elf";creation.ClassId="Wizard";creation.BackgroundId="Sage";CharacterCreationRules.ApplyRecommendedAbilities(creation);CharacterCreationRules.ResetClassDependentChoices(creation);
creation.ClassSkillChoices=[Skill.Investigation,Skill.Insight];creation.EquipmentPackageId="wizard-road";creation.CantripChoices=["fire-bolt","mage-hand","minor-illusion"];creation.SpellChoices=["magic-missile","shield","sleep","detect-magic","identify","thunderwave"];creation.PreparedSpellChoices=creation.SpellChoices.Take(CharacterCreationRules.PreparedSpellCount(creation)).ToList();
Check(CharacterCreationRules.Validate(creation,out var creationIssues)&&creationIssues.Count==0,"IIP47 a complete standard-array protagonist draft passes final legality validation");
var createdActor=CharacterCreationRules.BuildActor(creation);Check(createdActor.PlayerCreated&&createdActor.Name=="Aren Vale"&&createdActor.Pronouns=="they/them"&&createdActor.VoiceSet=="Wry"&&createdActor.Character.PrimaryClassName=="Wizard"&&createdActor.Character.Species=="Wood Elf","IIP47 identity, species, class, portrait/voice identity, and 5e sheet are built from player choices");
Check(createdActor.Character.Abilities.Dexterity==15&&createdActor.Character.Abilities.Intelligence==15&&createdActor.Character.Proficiencies.SkillRank(Skill.Arcana)==ProficiencyRank.Proficient&&createdActor.Character.Proficiencies.SkillRank(Skill.Investigation)==ProficiencyRank.Proficient,"IIP47 ancestry bonuses, standard array, background skills, and class skill choices feed the authoritative character model");
var createdSource=createdActor.Character.Spellcasting.Single(s=>s.SourceId=="Wizard");Check(createdSource.Cantrips.Count==3&&createdSource.KnownSpells.Count==6&&createdSource.PreparedSpells.Count==CharacterCreationRules.PreparedSpellCount(creation)&&createdSource.Slots.Single(s=>s.Level==1).Maximum==2,"IIP47 wizard creation produces legal cantrips, spellbook, prepared spells, and level-1 slots");
var createdWorld=World.New(creation);Check(createdWorld.PartyCount==6&&createdWorld.PartyLeader.Id=="protagonist"&&createdWorld.PartyLeader.PlayerCreated&&!createdWorld.Party.Any(a=>a.Id=="rogue")&&createdWorld.Party.Any(a=>a.Id=="knight")&&createdWorld.Party.Any(a=>a.Id=="bard"),"IIP47 New Journey inserts the custom protagonist as leader while preserving five authored companions and the six-person party cap");
var illegalCreation=CharacterCreationRules.NewDraft();illegalCreation.Name="X";illegalCreation.ClassSkillChoices.Clear();Check(!CharacterCreationRules.Validate(illegalCreation,out var illegalIssues)&&illegalIssues.Count>0,"IIP47 incomplete or illegal creation choices are rejected with actionable validation reasons");
var creationSave=Path.Combine(Path.GetTempPath(),"ashen-iip47-character-"+Guid.NewGuid()+".json");createdWorld.Save(creationSave);var creationLoaded=World.Load(creationSave);Check(creationLoaded.Version==World.CurrentSaveVersion&&creationLoaded.PartyLeader.PlayerCreated&&creationLoaded.PartyLeader.Name=="Aren Vale"&&creationLoaded.PartyLeader.VoiceSet=="Wry","IIP47 custom protagonist identity persists through v15 saves");
var v14CreationRoot=JsonNode.Parse(File.ReadAllText(creationSave))!.AsObject();v14CreationRoot["Version"]=14;foreach(var node in v14CreationRoot["Actors"]!.AsArray())if(node is JsonObject actor){actor.Remove("PlayerCreated");actor.Remove("Pronouns");actor.Remove("VoiceSet");}File.WriteAllText(creationSave,v14CreationRoot.ToJsonString());var migratedCreation=World.Load(creationSave);Check(migratedCreation.Version==World.CurrentSaveVersion&&migratedCreation.Party.All(a=>!a.PlayerCreated)&&migratedCreation.Party.All(a=>a.Pronouns=="they/them"),"IIP47 v14 journeys migrate to v15 with neutral identity defaults and never invent a player-created protagonist");File.Delete(creationSave);

